(7287318, 1135955, 42181, '<td valign="top">I like it and it works for the challenge, IMO it would have worked better without the rib.</td>', 'I like it and it works for the challenge, IMO it would have worked better without the rib.', '2014-11-24 03:31:50.000000', NULL, 1),
