(7287338, 1135929, 112828, '<td valign="top">Very nice.  More saturation might have been nice to emphasize those yellow stripes.  Really wonderful though, I think this has a real shot at a ribbon.</td>', 'Very nice.  More saturation might have been nice to emphasize those yellow stripes.  Really wonderful though, I think this has a real shot at a ribbon.', '2014-11-24 09:11:13.000000', NULL, 1),
(7287339, 1135788, 112828, '<td valign="top">Wild!</td>', 'Wild!', '2014-11-24 09:11:30.000000', NULL, 1),
(7287341, 1135853, 112828, '<td valign="top">Keystoning here really hurts the effect.  Just a bit of correction and a touch more saturation here (while making those dingy whites brighter) would have really made this a true top contender.   Great subject matter, awesome find.</td>', 'Keystoning here really hurts the effect.  Just a bit of correction and a touch more saturation here (while making those dingy whites brighter) would have really made this a true top contender.   Great subject matter, awesome find.', '2014-11-24 09:12:33.000000', NULL, 1),
(7287344, 1135868, 112828, '<td valign="top">Great use of a long lens here to compress the scene.  I find it a little too contrasty and dark, but overall a pretty cool image which is well suited to the challenge.</td>', 'Great use of a long lens here to compress the scene.  I find it a little too contrasty and dark, but overall a pretty cool image which is well suited to the challenge.', '2014-11-24 09:15:21.000000', NULL, 1),
