(7288630, 1135912, 97225, '<td valign="top">One of my favourites in this. I love the qualities of the photo - the light, the pastel colours, the simplified forms, the pov and composition - all work together beautifully in an aesthetically pleasing and interesting whole. One of my ribbon choices.</td>', 'One of my favourites in this. I love the qualities of the photo - the light, the pastel colours, the simplified forms, the pov and composition - all work together beautifully in an aesthetically pleasing and interesting whole. One of my ribbon choices.', '2014-11-30 20:03:00.000000', NULL, 1),
(7288631, 1135868, 97225, '<td valign="top">Wonderful pattern of layered houses - I love the colours and shapes, and the way they are distributed throughout the scene. One of my ribbon choices.</td>', 'Wonderful pattern of layered houses - I love the colours and shapes, and the way they are distributed throughout the scene. One of my ribbon choices.', '2014-11-30 20:05:33.000000', NULL, 1),
