(7288652, 1135809, 13077, '<td valign="top">Good detail in the water and the ship.</td>', 'Good detail in the water and the ship.', '2014-11-30 22:06:16.000000', NULL, 1),
(7288653, 1135789, 13077, '<td valign="top">The clouds really make this one. Nicely done and imitates his style well in my opinion.</td>', 'The clouds really make this one. Nicely done and imitates his style well in my opinion.', '2014-11-30 22:06:44.000000', NULL, 1),
(7288654, 1135615, 13077, '<td valign="top">Imagining it that way it would imitate his work well.</td>', 'Imagining it that way it would imitate his work well.', '2014-11-30 22:07:09.000000', NULL, 1),
(7288655, 1135913, 13077, '<td valign="top">I like the shapes and tones of this one. Maybe not something he would shoot, but the overall composition isn''t too far off, if we imagine the subjects to be larger things.</td>', 'I like the shapes and tones of this one. Maybe not something he would shoot, but the overall composition isn''t too far off, if we imagine the subjects to be larger things.', '2014-11-30 22:08:13.000000', NULL, 1),
(7288656, 1135930, 13077, '<td valign="top">Burned up? Interesting.</td>', 'Burned up? Interesting.', '2014-11-30 22:08:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7288657, 1135909, 13077, '<td valign="top">Beautiful scene and light.</td>', 'Beautiful scene and light.', '2014-11-30 22:08:43.000000', NULL, 1),
(7288658, 1135902, 13077, '<td valign="top">Well layered and very 2 dimensional.</td>', 'Well layered and very 2 dimensional.', '2014-11-30 22:09:06.000000', NULL, 1),
(7288659, 1135929, 13077, '<td valign="top">Excellent perspective and the composition is perfect. It has a very barren feel with the absence of people, and the green glow coming out from inside the escalators is fascinating.</td>', 'Excellent perspective and the composition is perfect. It has a very barren feel with the absence of people, and the green glow coming out from inside the escalators is fascinating.', '2014-11-30 22:09:57.000000', NULL, 1),
(7288660, 1135786, 13077, '<td valign="top">Visually compelling and with some imagination not too far off.</td>', 'Visually compelling and with some imagination not too far off.', '2014-11-30 22:10:40.000000', NULL, 1),
(7288662, 1135942, 13077, '<td valign="top">The colors and patterns are good but it could use either more sharpness, or a lot less sharpness in my opinion.</td>', 'The colors and patterns are good but it could use either more sharpness, or a lot less sharpness in my opinion.', '2014-11-30 22:11:09.000000', NULL, 1),
(7288663, 1135947, 13077, '<td valign="top">Very tranquil scene.</td>', 'Very tranquil scene.', '2014-11-30 22:11:26.000000', NULL, 1),
(7288664, 1135823, 13077, '<td valign="top">I like the excitement of all the people in various places in the frame, going about their business. Great vantage point. The textures and shapes of the ground look good as well.</td>', 'I like the excitement of all the people in various places in the frame, going about their business. Great vantage point. The textures and shapes of the ground look good as well.', '2014-11-30 22:12:22.000000', NULL, 1),
(7288665, 1135900, 13077, '<td valign="top">Interesting and very cool.</td>', 'Interesting and very cool.', '2014-11-30 22:12:57.000000', NULL, 1),
(7288666, 1135939, 13077, '<td valign="top">It''s very detailed and 2 dimensional, but also a bit soft. Wonder if you might have been able to wait until they got closer, utilize the zoom/crop less and eliminate the tree branches?</td>', 'It''s very detailed and 2 dimensional, but also a bit soft. Wonder if you might have been able to wait until they got closer, utilize the zoom/crop less and eliminate the tree branches?', '2014-11-30 22:13:53.000000', NULL, 1),
(7288667, 1135901, 13077, '<td valign="top">Cool architecture, but either technically lacking or processed with a style I don''t feel compliments the photo.</td>', 'Cool architecture, but either technically lacking or processed with a style I don''t feel compliments the photo.', '2014-11-30 22:14:27.000000', NULL, 1),
(7288668, 1135607, 13077, '<td valign="top">Very well done - simple and complex at the same time, good backlight in varying degrees of intensity which breaks up the monotony of the scene, and top-notch composition.</td>', 'Very well done - simple and complex at the same time, good backlight in varying degrees of intensity which breaks up the monotony of the scene, and top-notch composition.', '2014-11-30 22:15:14.000000', NULL, 1),
(7288669, 1135924, 13077, '<td valign="top">Nicely composed and good colors, but the things near the left seem a bit blurred.</td>', 'Nicely composed and good colors, but the things near the left seem a bit blurred.', '2014-11-30 22:15:43.000000', NULL, 1),
(7288670, 1135734, 13077, '<td valign="top">Interesting stains and grime on the surface there. I like the simple composition and the grunginess combined with the green water gives it a toxic waste vibe.</td>', 'Interesting stains and grime on the surface there. I like the simple composition and the grunginess combined with the green water gives it a toxic waste vibe.', '2014-11-30 22:16:21.000000', NULL, 1),
(7288671, 1135845, 13077, '<td valign="top">WOW that''s contrasty. Well composed and meets the style well though.</td>', 'WOW that''s contrasty. Well composed and meets the style well though.', '2014-11-30 22:16:57.000000', NULL, 1),
(7288672, 1135751, 13077, '<td valign="top">A good vantage point, well composed and interesting scene, but technically lacking.</td>', 'A good vantage point, well composed and interesting scene, but technically lacking.', '2014-11-30 22:17:25.000000', NULL, 1),
(7288673, 1135741, 13077, '<td valign="top">I like it. Simple and good architecture detail, also good light and I like the clear blue sky.</td>', 'I like it. Simple and good architecture detail, also good light and I like the clear blue sky.', '2014-11-30 22:17:50.000000', NULL, 1),
(7288674, 1135788, 13077, '<td valign="top">Excellent. Meets the challenge very well, and it''s fascinating. I''d like to see this as a big print.</td>', 'Excellent. Meets the challenge very well, and it''s fascinating. I''d like to see this as a big print.', '2014-11-30 22:19:19.000000', NULL, 1),
(7288675, 1135933, 13077, '<td valign="top">I like the shadows and light, and good detail in the roof architecture.</td>', 'I like the shadows and light, and good detail in the roof architecture.', '2014-11-30 22:19:53.000000', NULL, 1),
(7288676, 1135853, 13077, '<td valign="top">Interesting. guess they use big forklift to get them down?</td>', 'Interesting. guess they use big forklift to get them down?', '2014-11-30 22:20:20.000000', NULL, 1),
(7288677, 1135956, 13077, '<td valign="top">Well composed, and imitates his style pretty well.</td>', 'Well composed, and imitates his style pretty well.', '2014-11-30 22:20:53.000000', NULL, 1),
(7288681, 1135788, 97225, '<td valign="top">Great pattern and intriguing glimpses into the interior.</td>', 'Great pattern and intriguing glimpses into the interior.', '2014-11-30 22:37:54.000000', NULL, 1),
(7288682, 1135929, 97225, '<td valign="top">Nice pattern - I love the colourful metallic gleam.</td>', 'Nice pattern - I love the colourful metallic gleam.', '2014-11-30 22:38:59.000000', NULL, 1),
(7288683, 1135919, 97225, '<td valign="top">Great layers. It''s all so orderly it makes me wonder if someone gets frantic if it gets disrupted by customers taking out stock to buy.</td>', 'Great layers. It''s all so orderly it makes me wonder if someone gets frantic if it gets disrupted by customers taking out stock to buy.', '2014-11-30 22:41:54.000000', NULL, 1),
(7288685, 1135913, 97225, '<td valign="top">Fascinating - love your title.</td>', 'Fascinating - love your title.', '2014-11-30 22:43:14.000000', NULL, 1),
(7288695, 1135788, 100831, '<td valign="top">Wildly entertaining.</td>', 'Wildly entertaining.', '2014-11-30 23:24:43.000000', NULL, 1),
(7288696, 1135934, 100831, '<td valign="top">Love the possibilities.</td>', 'Love the possibilities.', '2014-11-30 23:25:14.000000', NULL, 1),
(7288697, 1135786, 100831, '<td valign="top">This would look excellent LARGE... so yes, the temptation is there.</td>', 'This would look excellent LARGE... so yes, the temptation is there.', '2014-11-30 23:26:48.000000', NULL, 1),
(7288698, 1135607, 100831, '<td valign="top">the repetition is almost endearing. So glad this is in color.</td>', 'the repetition is almost endearing. So glad this is in color.', '2014-11-30 23:27:36.000000', NULL, 1),
(7288699, 1135935, 100831, '<td valign="top">the detail is definitely Gurskyish... the light is gorgeous... just not sure about angle and perspective, but I like it well enough .. 7</td>', 'the detail is definitely Gurskyish... the light is gorgeous... just not sure about angle and perspective, but I like it well enough .. 7', '2014-11-30 23:31:15.000000', NULL, 1),
(7288700, 1135868, 100831, '<td valign="top">I really like the contrast and colors. Nice picture for the challenge. bump</td>', 'I really like the contrast and colors. Nice picture for the challenge. bump', '2014-11-30 23:32:53.000000', NULL, 1),
(7288702, 1135877, 100831, '<td valign="top">Excellent. Patterns and existences abound.</td>', 'Excellent. Patterns and existences abound.', '2014-11-30 23:56:52.000000', NULL, 1),
(7288703, 1135789, 100831, '<td valign="top">one of my favorites for this challenge.</td>', 'one of my favorites for this challenge.', '2014-11-30 23:57:47.000000', NULL, 1),
