(7288711, 1135788, 114285, '<td valign="top">A big congrats George on  a new PB and almighty score and ribbon, awesome find.</td>', 'A big congrats George on  a new PB and almighty score and ribbon, awesome find.', '2014-12-01 00:05:37.000000', NULL, 0),
(7288712, 1135868, 138630, '<td valign="top">One of my two 10''s - the 60''s song "Little Boxes" kept running through my head.  Even though these houses don''t look quite similar enough to qualify for ticky tacky, the image is fascinating.  Congratulations on the HM</td>', 'One of my two 10''s - the 60''s song "Little Boxes" kept running through my head.  Even though these houses don''t look quite similar enough to qualify for ticky tacky, the image is fascinating.  Congratulations on the HM', '2014-12-01 00:05:52.000000', NULL, 0),
